import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {SCHOOLS,constellationNodes,equipSchool,resetConstellations,withDoctrines,conditionalMultiplier} from '../constellation-model.js';
import {nodesFor,availablePoints,nodeState,unlockNode} from '../skill-grid-model.js';import {defaultHero,compileTechnique,compileLoadoutTechnique,personalTechnique} from '../mako.js';import{Battle,makeEnemy}from'../battle.js?v=5.6.0';import{equipRecipe,loomTechnique}from'../recipe-loom.js';import{World}from'../world.js';
import{buildBlueprint,validBlueprint,blueprintProgress}from'../build-blueprints.js';
const make=(chapter=24)=>({chapter,mode:'field',recruited:[0,1,2],bosses:[],skillGrid:{},cores:['flame','earth','mend','ward','volt','tide','frost','gale','shade','gravity'],supports:['focus','quick','link','echo','field'],heroes:Array.from({length:7},(_,id)=>defaultHero(id,45))});
function train(s,school,{fork='surge',cap='cap',id=0}={}){for(const step of ['root',fork,'cadence',cap])assert.ok(unlockNode(s,id,`discipline:${school}:${step}`),school+':'+step);}
test('twelve schools add 72 stable noncolliding nodes per hero while retaining all original IDs',()=>{assert.equal(SCHOOLS.length,12);assert.equal(constellationNodes().length,72);for(let id=0;id<7;id++){const n=nodesFor(id);assert.equal(n.length,132);assert.equal(new Set(n.map(n=>n.id)).size,n.length);for(const original of ['origin','0:0','6:7','mako:anchorheart'])assert.ok(n.some(n=>n.id===original));}});
test('forks are exclusive, prerequisites and chapter gates are enforced without spending on failure',()=>{const s=make(2),before=availablePoints(s,0);assert.equal(unlockNode(s,0,'discipline:kiln:cap'),false);assert.equal(availablePoints(s,0),before);assert.ok(unlockNode(s,0,'discipline:kiln:root'));assert.equal(unlockNode(s,0,'discipline:kiln:surge'),false);s.chapter=24;assert.ok(unlockNode(s,0,'discipline:kiln:economy'));const at=availablePoints(s,0);assert.equal(unlockNode(s,0,'discipline:kiln:surge'),false);assert.equal(availablePoints(s,0),at);assert.ok(unlockNode(s,0,'discipline:kiln:cadence'));assert.ok(unlockNode(s,0,'discipline:kiln:memory'));assert.equal(unlockNode(s,0,'discipline:kiln:cap'),false);});
test('two slots reject double majors, duplicates, unlearned schools, reserves and midbattle changes',()=>{const s=make();train(s,'kiln');train(s,'winter');train(s,'road');assert.ok(equipSchool(s,0,'kiln',0));assert.equal(equipSchool(s,0,'winter',1),false);assert.equal(equipSchool(s,0,'kiln',1),false);assert.equal(equipSchool(s,0,'mercy',1),false);assert.ok(equipSchool(s,0,'road',1));s.mode='battle';assert.equal(equipSchool(s,0,'winter',0),false);assert.equal(resetConstellations(s,0),false);assert.equal(unlockNode(s,0,'discipline:river:root'),false);});
test('free respec refunds only constellation spending and never changes stats, core AP or original nodes',()=>{const s=make();unlockNode(s,0,'0:0');const legacy=JSON.stringify(s.heroes[0]),points=availablePoints(s,0);train(s,'kiln');equipSchool(s,0,'kiln',0);assert.equal(availablePoints(s,0),points-8);const ap=JSON.stringify(s.heroes[0].ap),hp=s.heroes[0].maxHp;assert.ok(resetConstellations(s,0));assert.equal(availablePoints(s,0),points);assert.deepEqual(s.skillGrid[0],['0:0']);assert.equal(s.heroes[0].maxHp,hp);assert.equal(JSON.stringify(s.heroes[0].ap),ap);assert.deepEqual(s.heroes[0].doctrineBuild,[]);});
test('schools affect actual paid casts with conditional hits and the displayed MP cost',()=>{const s=make();train(s,'kiln');equipSchool(s,0,'kiln',0);const h=s.heroes[0];Object.assign(h,{x:0,y:0,atb:1});const e=makeEnemy('predator',20);Object.assign(e,{x:1,y:0,status:{burn:7}});const tech=compileLoadoutTechnique({core:'flame',support:'focus'},h,s),plain=compileTechnique('flame','focus',{character:0});assert.equal(tech.cost,plain.cost+1);assert.ok(tech.power>plain.power);assert.equal(conditionalMultiplier(h,e,tech),1.15);delete e.status.burn;assert.equal(conditionalMultiplier(h,e,tech),1);e.status.burn=7;const b=new Battle({heroes:[h],enemies:[e]});h.atb=1;h.strain=40;const mp=h.mp,old=e.hp;assert.ok(b.command(0,'tech',e.id,tech));assert.equal(h.mp,mp-tech.cost);assert.ok(e.hp<old);assert.equal(h.strain,40);assert.equal(h.ap.flame,3);});
test('mastery fork improves paid AP without free casts; discounts, power and rebates stay bounded',()=>{const s=make();train(s,'kiln',{fork:'economy',cap:'memory'});train(s,'road',{fork:'economy',cap:'memory'});equipSchool(s,0,'kiln',0);equipSchool(s,0,'road',1);const h=s.heroes[0],base=compileTechnique('flame','quick'),t=withDoctrines(h,base);assert.ok(t.cost>=Math.ceil(base.cost*.8));assert.ok(t.cost>=2);assert.equal(t.masteryBonus,2);assert.ok(t.strainRebate<=4);assert.deepEqual(withDoctrines(h,t),t);h.mp=0;h.hp=1;h.strain=99;const e=makeEnemy('predator',3);Object.assign(e,{x:1,y:0});Object.assign(h,{x:0,y:0});const b=new Battle({heroes:[h],enemies:[e]});h.atb=1;const before=JSON.stringify(h);assert.equal(b.command(0,'tech',e.id,t),false);assert.equal(JSON.stringify(h),before);});
test('all 48 school paths have bounded resource and damage effects across recipes and target states',()=>{for(const school of SCHOOLS)for(const fork of ['surge','economy'])for(const cap of ['cap','memory']){const s=make();train(s,school.id,{fork,cap});equipSchool(s,0,school.id,0);const h=s.heroes[0];for(const core of s.cores)for(const support of s.supports){const base=compileTechnique(core,support),t=withDoctrines(h,base);assert.ok(Number.isFinite(t.power)&&t.power>=base.power*.85&&t.power<=base.power*1.28);assert.ok(t.cost>=2&&t.cost>=Math.ceil(base.cost*.8));for(const hp of [10,h.maxHp]){h.hp=hp;const m=conditionalMultiplier(h,{hp:1,maxHp:100,armor:30,status:{wet:7,burn:7,slow:7,exposed:7}},t);assert.ok(m>=1&&m<=1.3);}}}});
test('recipe loom equips only discovered recipes and valid sockets, preserving compatible rare Mako',()=>{const s=make(),h=s.heroes[0];h.loadout[0].makoId='anchorheart';assert.ok(equipRecipe(s,0,0,'earth','focus'));assert.equal(h.loadout[0].makoId,'anchorheart');assert.ok(equipRecipe(s,0,0,'flame','echo'));assert.equal(h.loadout[0].makoId,undefined);assert.equal(equipRecipe(s,0,99,'earth','focus'),false);assert.equal(equipRecipe(s,0,0,'earth','unknown'),false);s.mode='battle';assert.equal(equipRecipe(s,0,0,'earth','focus'),false);});
test('constellations and equipped builds roundtrip through the real World save and personal arts use the same costs',()=>{const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));const w=new World(data),s=w.state;s.chapter=24;s.recruited=[0];Object.assign(s.heroes[0],defaultHero(0,45));train(s,'stone');equipSchool(s,0,'stone',0);const before=compileLoadoutTechnique({core:'earth',support:'focus'},s.heroes[0],s);w.restore(w.save());assert.deepEqual(w.state.heroes[0].doctrineSlots,['stone',null]);assert.equal(compileLoadoutTechnique({core:'earth',support:'focus'},w.state.heroes[0],w.state).cost,before.cost);assert.equal(personalTechnique(w.state.heroes[0],5,'Sky Rend').doctrineApplied,true);});
test('saved blueprints are plans only and reject impossible forks, malformed schools and unknown node IDs',()=>{const s=make();train(s,'stone');equipSchool(s,0,'stone',0);const p=buildBlueprint(s,0);assert.ok(validBlueprint(p));const fresh=make(1),before=JSON.stringify(fresh);assert.deepEqual(blueprintProgress(p,fresh),{learned:0,total:4,remainingCost:8,lastChapter:12});assert.equal(JSON.stringify(fresh),before);assert.equal(validBlueprint({...p,nodes:[...p.nodes,'discipline:stone:economy']}),false);assert.equal(validBlueprint({...p,nodes:['discipline:stone:cap']}),false);assert.equal(validBlueprint({...p,schools:['stone','kiln']}),false);assert.equal(validBlueprint({...p,nodes:['grant-everything']}),false);});
test('all legal paired schools obey global ceilings even at their strongest conditional state',()=>{const target={hp:1,maxHp:100,armor:100,status:{burn:7,wet:7,slow:7,exposed:7}};for(let i=0;i<SCHOOLS.length;i++)for(let j=i+1;j<SCHOOLS.length;j++){if(SCHOOLS[i].weight+SCHOOLS[j].weight>3)continue;const s=make();train(s,SCHOOLS[i].id);train(s,SCHOOLS[j].id);equipSchool(s,0,SCHOOLS[i].id,0);equipSchool(s,0,SCHOOLS[j].id,1);const h=s.heroes[0];h.hp=1;h.status={guard:7};for(const core of s.cores)for(const support of ['focus','link','echo','field','quick','counter','break']){const base=compileTechnique(core,support),t=withDoctrines(h,base);assert.ok(t.power<=base.power*1.28);assert.ok(conditionalMultiplier(h,target,t)<=1.3);assert.ok(t.strainRebate<=4);}}});

test('loom preview includes the destination socket’s compatible rare crystal and predicts the equipped MP cost',()=>{const s=make();s.kakeya={relics:['anchorheart']};s.skillGrid[0]=['mako:anchorheart'];s.heroes[0].loadout[0]={core:'earth',support:'focus',makoId:'anchorheart'};const preview=loomTechnique(s,0,0,'earth','quick');assert.equal(preview.makoId,'anchorheart');assert.ok(equipRecipe(s,0,0,'earth','quick'));assert.equal(preview.cost,compileLoadoutTechnique(s.heroes[0].loadout[0],s.heroes[0],s).cost);assert.equal(loomTechnique(s,0,0,'flame','focus').makoId,undefined);});
